
// generate this file by scripts/genarate-example-entry.mjs
import React from "react";

export default {
  "accordion-demo": {
    component: React.lazy(() => import("./accordion-demo")),
    codeString: "import { Accordion } from \"@/registry/ui/accordion\";\n\nconst Demo = () => (\n  <div className=\"space-y-8\">\n    <Accordion\n      defaultValue={[\"shipping\"]}\n      items={[\n        {\n          value: \"shipping\",\n          trigger: \"How long does shipping take?\",\n          content:\n            \"Orders ship within 1–2 business days and arrive in 3–5 days.\",\n        },\n        {\n          value: \"returns\",\n          trigger: \"What is the return policy?\",\n          content: \"Return any unused item within 30 days for a full refund.\",\n        },\n        {\n          value: \"support\",\n          trigger: \"How do I contact support?\",\n          content:\n            \"Email support@example.com — we reply within one business day.\",\n        },\n      ]}\n    />\n\n    <Accordion\n      defaultValue={[\"build\", \"deploy\"]}\n      items={[\n        {\n          value: \"build\",\n          trigger: \"Build\",\n          content: \"Multiple panels stay open at once with the multiple prop.\",\n        },\n        {\n          value: \"deploy\",\n          trigger: \"Deploy\",\n          content: \"Push to main and CI publishes the registry automatically.\",\n        },\n        {\n          disabled: true,\n          value: \"archive\",\n          trigger: \"Archive (disabled)\",\n          content: null,\n        },\n      ]}\n      multiple\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "alert-demo": {
    component: React.lazy(() => import("./alert-demo")),
    codeString: "\"use client\";\n\nimport { CircleAlertIcon, CircleCheckIcon } from \"lucide-react\";\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { Alert } from \"@/registry/ui/alert\";\n\nconst Demo = () => {\n  const [restored, setRestored] = useState(false);\n\n  return (\n    <div className=\"w-full max-w-xl space-y-4\">\n      <Alert\n        description=\"Your profile is ready for the next deployment.\"\n        title=\"Changes saved\"\n      />\n\n      <Alert\n        description=\"All checks passed and the release can continue.\"\n        icon={<CircleCheckIcon aria-hidden=\"true\" />}\n        title=\"Ready to deploy\"\n      />\n\n      <Alert\n        description=\"Reconnect your account before retrying this request.\"\n        icon={<CircleAlertIcon aria-hidden=\"true\" />}\n        title=\"Session expired\"\n        variant=\"destructive\"\n      />\n\n      <Alert\n        action={\n          <Button onClick={() => setRestored(true)} size=\"xs\" variant=\"outline\">\n            Undo\n          </Button>\n        }\n        description={\n          restored\n            ? \"The archived messages have been restored.\"\n            : \"Five messages were moved to the archive.\"\n        }\n        icon={<CircleAlertIcon aria-hidden=\"true\" />}\n        title={restored ? \"Messages restored\" : \"Messages archived\"}\n      />\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "alert-dialog-demo": {
    component: React.lazy(() => import("./alert-dialog-demo")),
    codeString: "import { AlertDialog } from \"@/registry/ui/alert-dialog\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\n\nconst Demo = () => (\n  <div className=\"flex flex-wrap gap-3\">\n    <AlertDialog\n      description=\"This action cannot be undone.\"\n      onConfirm={async () => {\n        await new Promise((resolve) => setTimeout(resolve, 800));\n      }}\n      title=\"Are you sure?\"\n      trigger={<AsyncButton variant=\"outline\">Async confirm</AsyncButton>}\n    />\n\n    <AlertDialog\n      confirmText=\"Delete\"\n      description=\"The project and all its data will be permanently removed.\"\n      title=\"Delete project?\"\n      trigger={<AsyncButton variant=\"destructive\">Delete</AsyncButton>}\n      variant=\"destructive\"\n    />\n\n    <AlertDialog\n      confirmText=\"Got it\"\n      description=\"Your changes have been saved successfully.\"\n      showCancel={false}\n      title=\"All done\"\n      trigger={<AsyncButton variant=\"outline\">Single action</AsyncButton>}\n    />\n\n    <AlertDialog\n      description=\"This footer replaces the entire button row.\"\n      footer={<AsyncButton className=\"w-full\">Custom footer</AsyncButton>}\n      title=\"Footer override\"\n      trigger={<AsyncButton variant=\"outline\">Custom footer</AsyncButton>}\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "async-button-demo": {
    component: React.lazy(() => import("./async-button-demo")),
    codeString: "\"use client\";\n\nimport {\n  ArrowRightIcon,\n  DownloadIcon,\n  RefreshCwIcon,\n  SendIcon,\n  Trash2Icon,\n} from \"lucide-react\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\n\nconst wait = (ms: number) =>\n  new Promise<void>((resolve) => {\n    setTimeout(() => {\n      resolve();\n    }, ms);\n  });\n\nconst Demo = () => (\n  <div className=\"flex flex-col gap-6\">\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Click the button — loading state activates automatically while the\n        promise is pending.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton onClick={() => wait(2000)}>Submit Order</AsyncButton>\n        <AsyncButton onClick={() => wait(2000)} variant=\"outline\">\n          Sync Data\n        </AsyncButton>\n        <AsyncButton onClick={() => wait(2000)} variant=\"secondary\">\n          Export Report\n        </AsyncButton>\n      </div>\n    </div>\n\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Drive loading externally via the <code>loading</code> prop.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton loading>Controlled Loading</AsyncButton>\n      </div>\n    </div>\n\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Use <code>startIcon</code> / <code>endIcon</code>. While loading, the\n        icon slot is swapped for the spinner — no overlay needed. When both are\n        present, <code>startIcon</code> takes the spinner.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton onClick={() => wait(2000)} startIcon={<SendIcon />}>\n          Send Message\n        </AsyncButton>\n        <AsyncButton\n          endIcon={<ArrowRightIcon />}\n          onClick={() => wait(2000)}\n          variant=\"outline\"\n        >\n          Continue\n        </AsyncButton>\n        <AsyncButton\n          endIcon={<ArrowRightIcon />}\n          onClick={() => wait(2000)}\n          startIcon={<DownloadIcon />}\n          variant=\"secondary\"\n        >\n          Download &amp; Next\n        </AsyncButton>\n      </div>\n    </div>\n\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Icon buttons — every <code>icon*</code> size swaps the lone icon for the\n        spinner.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton onClick={() => wait(2000)} size=\"icon-xs\" variant=\"ghost\">\n          <RefreshCwIcon />\n        </AsyncButton>\n        <AsyncButton\n          onClick={() => wait(2000)}\n          size=\"icon-sm\"\n          variant=\"outline\"\n        >\n          <RefreshCwIcon />\n        </AsyncButton>\n        <AsyncButton onClick={() => wait(2000)} size=\"icon\">\n          <SendIcon />\n        </AsyncButton>\n        <AsyncButton\n          onClick={() => wait(2000)}\n          size=\"icon-lg\"\n          variant=\"destructive\"\n        >\n          <Trash2Icon />\n        </AsyncButton>\n      </div>\n    </div>\n\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Anti-flash: a 50ms task still shows the spinner for at least 200ms (the\n        default <code>minDuration</code>), so the indicator never just flickers\n        past.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton onClick={() => wait(50)}>Fast Save (50ms)</AsyncButton>\n      </div>\n    </div>\n\n    <div className=\"flex flex-col gap-2\">\n      <p className=\"text-muted-foreground text-sm\">\n        Errors are caught and logged — the button recovers gracefully.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <AsyncButton\n          onClick={() =>\n            wait(1500).then(() => {\n              throw new Error(\"Request failed\");\n            })\n          }\n          variant=\"destructive\"\n        >\n          Simulate Failure\n        </AsyncButton>\n      </div>\n    </div>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "avatar-demo": {
    component: React.lazy(() => import("./avatar-demo")),
    codeString: "import { Avatar } from \"@/registry/ui/avatar\";\n\nconst Demo = () => (\n  <div className=\"grid w-full max-w-xl gap-6 sm:grid-cols-2\">\n    <section className=\"space-y-3\">\n      <h3 className=\"font-medium text-sm\">Fallback only</h3>\n      <Avatar fallback=\"AL\" />\n    </section>\n\n    <section className=\"space-y-3\">\n      <h3 className=\"font-medium text-sm\">Image with fallback</h3>\n      <Avatar\n        alt=\"Abstract blue and purple banner\"\n        fallback=\"BN\"\n        size=\"lg\"\n        src=\"/banner.png\"\n      />\n    </section>\n\n    <section className=\"space-y-3\">\n      <h3 className=\"font-medium text-sm\">Failed image</h3>\n      <Avatar\n        aria-label=\"Grace Hopper\"\n        fallback=\"GH\"\n        role=\"img\"\n        size=\"lg\"\n        src=\"/missing-avatar.png\"\n      />\n    </section>\n\n    <section className=\"space-y-3\">\n      <h3 className=\"font-medium text-sm\">Caller-owned badge</h3>\n      <Avatar\n        aria-label=\"Lin Chen, online\"\n        badge={<span aria-hidden=\"true\" />}\n        badgeClassName=\"bg-emerald-500\"\n        fallback=\"LC\"\n        role=\"img\"\n        size=\"lg\"\n      />\n    </section>\n\n    <section className=\"space-y-3 sm:col-span-2\">\n      <h3 className=\"font-medium text-sm\">Primitive sizes</h3>\n      <div className=\"flex items-end gap-4\">\n        <Avatar aria-label=\"Small avatar\" fallback=\"SM\" role=\"img\" size=\"sm\" />\n        <Avatar aria-label=\"Default avatar\" fallback=\"DF\" role=\"img\" />\n        <Avatar aria-label=\"Large avatar\" fallback=\"LG\" role=\"img\" size=\"lg\" />\n      </div>\n    </section>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "breadcrumb-demo": {
    component: React.lazy(() => import("./breadcrumb-demo")),
    codeString: "import { Breadcrumb } from \"@/registry/ui/breadcrumb\";\n\nconst trail = [\n  { href: \"/\", label: \"Home\" },\n  { href: \"/docs\", label: \"Docs\" },\n  { href: \"/docs/components\", label: \"Components\" },\n  { label: \"Breadcrumb\" },\n];\n\nconst Demo = () => (\n  <div className=\"space-y-8\">\n    <Breadcrumb items={trail} />\n\n    <Breadcrumb items={trail} separator=\"/\" />\n\n    <Breadcrumb items={trail} maxItems={3} />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "calendar-demo": {
    component: React.lazy(() => import("./calendar-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport type { DateRange } from \"react-day-picker\";\nimport { Calendar } from \"@/registry/ui/calendar\";\n\nconst Demo = () => {\n  const [single, setSingle] = useState<Date | undefined>();\n  const [monthsDate, setMonthsDate] = useState<Date | undefined>();\n  const [yearsDate, setYearsDate] = useState<Date | undefined>();\n  const [multiple, setMultiple] = useState<Date[] | undefined>();\n  const [range, setRange] = useState<DateRange | undefined>();\n\n  return (\n    <div className=\"flex flex-col gap-6\">\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Days view — click month or year in the caption\n        </span>\n        <Calendar mode=\"single\" onSelect={setSingle} selected={single} />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Months view (defaultView=&quot;months&quot;)\n        </span>\n        <Calendar\n          defaultView=\"months\"\n          mode=\"single\"\n          onSelect={setMonthsDate}\n          selected={monthsDate}\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Years view (defaultView=&quot;years&quot;)\n        </span>\n        <Calendar\n          defaultView=\"years\"\n          mode=\"single\"\n          onSelect={setYearsDate}\n          selected={yearsDate}\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Multiple — click multiple days to toggle selection\n        </span>\n        <Calendar mode=\"multiple\" onSelect={setMultiple} selected={multiple} />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Range — pick a start and end day\n        </span>\n        <Calendar mode=\"range\" onSelect={setRange} selected={range} />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "card-demo": {
    component: React.lazy(() => import("./card-demo")),
    codeString: "import { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Card } from \"@/registry/ui/card\";\n\nconst Demo = () => (\n  <div className=\"space-y-4\">\n    <Card\n      action={<AsyncButton variant=\"outline\">More</AsyncButton>}\n      className=\"w-128\"\n      description=\"some descriptions\"\n      footer={<AsyncButton>Button</AsyncButton>}\n      footerClassName=\"flex justify-end\"\n      title=\"Default Card\"\n    >\n      <div>\n        <div>No dividers</div>\n        <div>No dividers</div>\n        <div>No dividers</div>\n      </div>\n    </Card>\n\n    <Card\n      className=\"w-72\"\n      contentClassName=\"bg-white\"\n      description=\"using className\"\n      descriptionClassName=\"text-gray-500\"\n      dividers\n      footer=\"Custom Card Footer\"\n      size=\"sm\"\n      title=\"Small Card\"\n    >\n      <ul>\n        <li>Size: sm</li>\n        <li>dividers: true</li>\n      </ul>\n    </Card>\n\n    <Card\n      className=\"w-72\"\n      dividers={{ footer: true }}\n      footer=\"Footer divider only\"\n    >\n      Content-only card without header slots.\n    </Card>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "carousel-demo": {
    component: React.lazy(() => import("./carousel-demo")),
    codeString: "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport {\n  Carousel,\n  type CarouselApi,\n  type CarouselItem,\n} from \"@/registry/ui/carousel\";\n\nconst PROJECTS: CarouselItem[] = [\n  { item: \"Transit map\", value: \"transit-map\" },\n  { item: \"Station board\", value: \"station-board\" },\n  { item: \"Route planner\", value: \"route-planner\" },\n];\n\nconst useSelectedSlide = () => {\n  const [api, setApi] = useState<CarouselApi>();\n  const [selectedSlide, setSelectedSlide] = useState(0);\n\n  useEffect(() => {\n    if (!api) {\n      return;\n    }\n\n    const syncSelectedSlide = () => setSelectedSlide(api.selectedScrollSnap());\n    syncSelectedSlide();\n    api.on(\"reInit\", syncSelectedSlide);\n    api.on(\"select\", syncSelectedSlide);\n\n    return () => {\n      api.off(\"reInit\", syncSelectedSlide);\n      api.off(\"select\", syncSelectedSlide);\n    };\n  }, [api]);\n\n  return { selectedSlide, setApi };\n};\n\nconst Slide = ({ children }: { children: string }) => (\n  <div className=\"flex h-40 items-center justify-center rounded-xl border bg-muted/40 font-medium text-lg\">\n    {children}\n  </div>\n);\n\nconst Demo = () => {\n  const horizontal = useSelectedSlide();\n  const vertical = useSelectedSlide();\n\n  return (\n    <div className=\"grid w-full max-w-4xl gap-12 lg:grid-cols-2\">\n      <section className=\"space-y-4 px-12\">\n        <h3 className=\"font-medium text-sm\">Horizontal</h3>\n        <Carousel\n          aria-label=\"Featured projects\"\n          className=\"mx-auto w-full max-w-sm\"\n          itemClassName=\"basis-4/5\"\n          items={PROJECTS.map((project) => ({\n            ...project,\n            item: <Slide>{String(project.item)}</Slide>,\n            itemClassName:\n              project.value === \"station-board\" ? \"basis-full\" : undefined,\n          }))}\n          setApi={horizontal.setApi}\n          tabIndex={0}\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-center text-muted-foreground text-xs\"\n          data-carousel-status=\"horizontal\"\n          role=\"status\"\n        >\n          Slide {horizontal.selectedSlide + 1} of {PROJECTS.length}\n        </p>\n      </section>\n\n      <section className=\"space-y-4 px-12 py-12\">\n        <h3 className=\"font-medium text-sm\">Vertical</h3>\n        <Carousel\n          aria-label=\"Project timeline\"\n          className=\"mx-auto w-full max-w-sm\"\n          contentClassName=\"h-40\"\n          items={PROJECTS.map((project) => ({\n            ...project,\n            item: <Slide>{String(project.item)}</Slide>,\n          }))}\n          opts={{ align: \"start\", loop: true }}\n          orientation=\"vertical\"\n          setApi={vertical.setApi}\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-center text-muted-foreground text-xs\"\n          data-carousel-status=\"vertical\"\n          role=\"status\"\n        >\n          Slide {vertical.selectedSlide + 1} of {PROJECTS.length}\n        </p>\n      </section>\n\n      <section className=\"space-y-4 px-12 lg:col-span-2\">\n        <h3 className=\"font-medium text-sm\">Single item</h3>\n        <Carousel\n          aria-label=\"Featured release\"\n          className=\"mx-auto w-full max-w-sm\"\n          items={[\n            {\n              item: <Slide>Version 2.0</Slide>,\n              value: \"version-2\",\n            },\n          ]}\n        />\n        <p className=\"text-center text-muted-foreground text-xs\">\n          One slide keeps its landmark and omits both controls.\n        </p>\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "checkbox-demo": {
    component: React.lazy(() => import("./checkbox-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { Checkbox } from \"@/registry/ui/checkbox\";\n\nconst Demo = () => {\n  const [controlled, setControlled] = useState(false);\n  const [submitted, setSubmitted] = useState(\"not submitted\");\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-6 sm:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Basic</h3>\n        <Checkbox label=\"Accept terms and conditions\" />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">With description</h3>\n        <Checkbox\n          description=\"Receive a concise weekly summary.\"\n          label=\"Weekly summary\"\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Controlled</h3>\n        <Checkbox\n          checked={controlled}\n          label=\"Team access\"\n          onCheckedChange={setControlled}\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-muted-foreground text-xs\"\n          role=\"status\"\n        >\n          Controlled value: {controlled ? \"checked\" : \"unchecked\"}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">States</h3>\n        <div className=\"space-y-3\">\n          <Checkbox disabled label=\"Disabled option\" />\n          <Checkbox defaultChecked label=\"Read-only option\" readOnly />\n        </div>\n      </section>\n\n      <section className=\"space-y-3 sm:col-span-2\">\n        <h3 className=\"font-medium text-sm\">Native form</h3>\n        <form\n          className=\"space-y-3\"\n          onSubmit={(event) => {\n            event.preventDefault();\n            const data = new FormData(event.currentTarget);\n            setSubmitted(String(data.get(\"digest\") ?? \"missing\"));\n          }}\n        >\n          <Checkbox\n            label=\"Email digest\"\n            name=\"digest\"\n            uncheckedValue=\"disabled\"\n            value=\"enabled\"\n          />\n          <Button size=\"sm\" type=\"submit\" variant=\"outline\">\n            Submit form\n          </Button>\n          <p\n            aria-live=\"polite\"\n            className=\"text-muted-foreground text-xs\"\n            role=\"status\"\n          >\n            Submitted value: {submitted}\n          </p>\n        </form>\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "checkbox-group-demo": {
    component: React.lazy(() => import("./checkbox-group-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { CheckboxGroup } from \"@/registry/ui/checkbox-group\";\n\nconst Demo = () => {\n  const [value, setValue] = useState<string[]>([\"email\"]);\n\n  return (\n    <div className=\"space-y-8\">\n      {/* Uncontrolled with defaultValue */}\n      <CheckboxGroup\n        defaultValue={[\"comfortable\"]}\n        items={[\n          { label: \"Default\", value: \"default\" },\n          { label: \"Comfortable\", value: \"comfortable\" },\n          { disabled: true, label: \"Compact (disabled)\", value: \"compact\" },\n        ]}\n      />\n\n      {/* Uncontrolled with descriptions */}\n      <CheckboxGroup\n        defaultValue={[\"analytics\"]}\n        items={[\n          {\n            description: \"Track visits and conversions.\",\n            label: \"Analytics\",\n            value: \"analytics\",\n          },\n          {\n            description: \"Personalize content and ads.\",\n            label: \"Marketing\",\n            value: \"marketing\",\n          },\n        ]}\n      />\n\n      {/* Controlled */}\n      <CheckboxGroup\n        items={[\n          { label: \"Email\", value: \"email\" },\n          { label: \"SMS\", value: \"sms\" },\n          { label: \"Push\", value: \"push\" },\n        ]}\n        onValueChange={setValue}\n        value={value}\n      />\n\n      {/* Styled via class overrides */}\n      <CheckboxGroup\n        descriptionClassName=\"text-gray-500\"\n        items={[\n          {\n            description: \"This whole group is disabled.\",\n            label: \"Locked\",\n            value: \"locked\",\n          },\n        ]}\n        labelClassName=\"font-semibold\"\n      />\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "combobox-demo": {
    component: React.lazy(() => import("./combobox-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Combobox, type ComboboxItem } from \"@/registry/ui/combobox\";\n\nconst FRUITS: ComboboxItem[] = [\n  { label: \"Apple\", value: \"apple\" },\n  { label: \"Banana\", value: \"banana\" },\n  { label: \"Blueberry\", value: \"blueberry\" },\n  { label: \"Cherry\", value: \"cherry\" },\n  { label: \"Grapes\", value: \"grapes\" },\n  { label: \"Mango (out of stock)\", value: \"mango\", disabled: true },\n  { label: \"Pineapple\", value: \"pineapple\" },\n];\n\nconst Demo = () => {\n  const [value, setValue] = useState<string | undefined>(\"banana\");\n  const [submitted, setSubmitted] = useState<string | null>(null);\n\n  return (\n    <div className=\"flex max-w-sm flex-col gap-6\">\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Uncontrolled — type to filter, click to select.\n        </span>\n        <Combobox items={FRUITS} placeholder=\"Pick a fruit\" />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Controlled + clearable — selected: {value ?? \"none\"}\n        </span>\n        <Combobox\n          clearable\n          items={FRUITS}\n          onValueChange={setValue}\n          value={value}\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Custom filter — matches the start of the label only.\n        </span>\n        <Combobox\n          filter={(item, query) =>\n            String(item.label).toLowerCase().startsWith(query.toLowerCase())\n          }\n          items={FRUITS}\n          placeholder=\"Prefix search\"\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">Disabled.</span>\n        <Combobox disabled items={FRUITS} placeholder=\"Unavailable\" />\n      </div>\n\n      <form\n        className=\"flex flex-col gap-2\"\n        onSubmit={(e) => {\n          e.preventDefault();\n          const data = new FormData(e.currentTarget);\n          setSubmitted(String(data.get(\"fruit\") || \"(empty)\"));\n        }}\n      >\n        <label className=\"text-muted-foreground text-sm\" htmlFor=\"fruit-field\">\n          Form integration — submits via a hidden input.\n        </label>\n        <Combobox\n          defaultValue=\"cherry\"\n          id=\"fruit-field\"\n          items={FRUITS}\n          name=\"fruit\"\n        />\n        <button\n          className=\"w-fit rounded-md border px-3 py-1 text-sm\"\n          type=\"submit\"\n        >\n          Submit\n        </button>\n        {submitted !== null && (\n          <span className=\"text-muted-foreground text-sm\">\n            Submitted: {submitted}\n          </span>\n        )}\n      </form>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "date-picker-demo": {
    component: React.lazy(() => import("./date-picker-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport type { DateRange } from \"react-day-picker\";\nimport { DatePicker } from \"@/registry/ui/date-picker\";\n\nconst Demo = () => {\n  const [single, setSingle] = useState<Date | undefined>();\n  const [multiple, setMultiple] = useState<Date[] | undefined>();\n  const [range, setRange] = useState<DateRange | undefined>();\n  const [typed, setTyped] = useState<Date | undefined>();\n  const [appointment, setAppointment] = useState<Date | undefined>();\n\n  return (\n    <div className=\"flex flex-col gap-6\">\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Single (default trigger, format=&quot;PPP&quot;)\n        </span>\n        <DatePicker onChange={setSingle} value={single} />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Multiple (single panel, format=&quot;LLL dd, y&quot;)\n        </span>\n        <DatePicker\n          format=\"LLL dd, y\"\n          mode=\"multiple\"\n          onChange={setMultiple}\n          value={multiple}\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Range (single panel, format=&quot;LLL dd, y&quot;)\n        </span>\n        <DatePicker\n          format=\"LLL dd, y\"\n          mode=\"range\"\n          onChange={setRange}\n          value={range}\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          With input (format=&quot;yyyy-MM-dd&quot;)\n        </span>\n        <DatePicker\n          format=\"yyyy-MM-dd\"\n          onChange={setTyped}\n          value={typed}\n          withInput\n        />\n      </div>\n\n      <div className=\"flex flex-col gap-2\">\n        <span className=\"text-muted-foreground text-sm\">\n          Constrained (minDate=today, weekends disabled)\n        </span>\n        <DatePicker\n          disabledDates={{ dayOfWeek: [0, 6] }}\n          minDate={new Date()}\n          onChange={setAppointment}\n          value={appointment}\n        />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "dropdown-menu-demo": {
    component: React.lazy(() => import("./dropdown-menu-demo")),
    codeString: "\"use client\";\n\nimport {\n  CopyIcon,\n  MoreHorizontalIcon,\n  PencilIcon,\n  Trash2Icon,\n} from \"lucide-react\";\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { DropdownMenu } from \"@/registry/ui/dropdown-menu\";\n\nconst Demo = () => {\n  const [controlledOpen, setControlledOpen] = useState(false);\n  const [lastAction, setLastAction] = useState(\"None\");\n\n  return (\n    <div className=\"grid w-full max-w-3xl gap-6 sm:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Basic</h3>\n        <DropdownMenu\n          items={[\n            { content: \"Edit\", value: \"edit\" },\n            { content: \"Duplicate\", value: \"duplicate\" },\n            { content: \"Archive\", value: \"archive\" },\n          ]}\n          trigger={<Button variant=\"outline\">Open actions</Button>}\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Controlled and observable</h3>\n        <DropdownMenu\n          items={[\n            {\n              content: \"Rename project\",\n              onClick: () => setLastAction(\"Rename project\"),\n              value: \"rename\",\n            },\n            {\n              content: \"Duplicate project\",\n              onClick: () => setLastAction(\"Duplicate project\"),\n              value: \"duplicate\",\n            },\n          ]}\n          onOpenChange={setControlledOpen}\n          open={controlledOpen}\n          trigger={<Button variant=\"outline\">Project actions</Button>}\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-muted-foreground text-xs\"\n          role=\"status\"\n        >\n          Menu: {controlledOpen ? \"open\" : \"closed\"}; last action: {lastAction}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Presentation</h3>\n        <DropdownMenu\n          items={[\n            {\n              content: \"Edit\",\n              icon: <PencilIcon />,\n              shortcut: \"⌘E\",\n              value: \"edit\",\n            },\n            {\n              content: \"Duplicate\",\n              icon: <CopyIcon />,\n              shortcut: \"⌘D\",\n              value: \"duplicate\",\n            },\n            {\n              content: \"Move without icon\",\n              inset: true,\n              value: \"move\",\n            },\n            {\n              content: \"Delete\",\n              icon: <Trash2Icon />,\n              shortcut: \"⌫\",\n              value: \"delete\",\n              variant: \"destructive\",\n            },\n          ]}\n          trigger={\n            <Button\n              aria-label=\"Open presentation menu\"\n              size=\"icon\"\n              variant=\"outline\"\n            >\n              <MoreHorizontalIcon />\n            </Button>\n          }\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Disabled states</h3>\n        <div className=\"flex flex-wrap gap-2\">\n          <DropdownMenu\n            disabled\n            items={[{ content: \"Unavailable action\", value: \"unavailable\" }]}\n            trigger={<Button variant=\"outline\">Disabled menu</Button>}\n          />\n          <DropdownMenu\n            items={[\n              { content: \"Available action\", value: \"available\" },\n              {\n                content: \"Disabled action\",\n                disabled: true,\n                value: \"disabled\",\n              },\n            ]}\n            trigger={<Button variant=\"outline\">Mixed actions</Button>}\n          />\n        </div>\n      </section>\n\n      <section className=\"space-y-3 sm:col-span-2\">\n        <h3 className=\"font-medium text-sm\">Position and classes</h3>\n        <DropdownMenu\n          align=\"end\"\n          contentClassName=\"w-56\"\n          itemClassName=\"py-2\"\n          items={[\n            {\n              content: \"Open above the trigger\",\n              itemClassName: \"font-medium\",\n              shortcut: \"⌘O\",\n              value: \"open\",\n            },\n          ]}\n          shortcutClassName=\"text-primary\"\n          side=\"top\"\n          sideOffset={8}\n          trigger={<Button variant=\"outline\">Positioned menu</Button>}\n        />\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "field-demo": {
    component: React.lazy(() => import("./field-demo")),
    codeString: "import { Checkbox } from \"@/components/ui/checkbox\";\nimport { Input } from \"@/components/ui/input\";\nimport { Textarea } from \"@/components/ui/textarea\";\nimport {\n  Field,\n  FieldContent,\n  FieldDescription,\n  FieldLabel,\n  FieldTitle,\n} from \"@/registry/ui/field\";\nimport { Select } from \"@/registry/ui/select\";\n\nconst roleItems = [\n  { label: \"Owner\", value: \"owner\" },\n  { label: \"Admin\", value: \"admin\" },\n  { label: \"Member\", value: \"member\" },\n];\n\nconst Demo = () => (\n  <div className=\"w-full max-w-md space-y-5\">\n    <Field\n      description=\"Used for workspace notifications.\"\n      label=\"Email\"\n      required\n    >\n      <Input placeholder=\"ada@example.com\" type=\"email\" />\n    </Field>\n\n    <Field\n      description=\"Controls billing and member management access.\"\n      label=\"Role\"\n    >\n      <Select items={roleItems} placeholder=\"Pick a role\" />\n    </Field>\n\n    <Field error=\"Bio must be at least 20 characters.\" label=\"Bio\">\n      <Textarea placeholder=\"Tell the team what this person owns.\" />\n    </Field>\n\n    <Field orientation=\"horizontal\">\n      <Checkbox id=\"weekly-summary\" />\n      <FieldContent>\n        <FieldLabel htmlFor=\"weekly-summary\">Weekly summary</FieldLabel>\n        <FieldDescription>Send a short digest every Monday.</FieldDescription>\n      </FieldContent>\n    </Field>\n\n    <Field orientation=\"horizontal\">\n      <Checkbox id=\"touch-id\" />\n      <FieldContent>\n        <FieldTitle>Touch ID</FieldTitle>\n        <FieldDescription>Unlock your workspace faster.</FieldDescription>\n      </FieldContent>\n    </Field>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "field-form-demo": {
    component: React.lazy(() => import("./field-form-demo")),
    codeString: "\"use client\";\n\nimport { standardSchemaResolver } from \"@hookform/resolvers/standard-schema\";\nimport { useForm } from \"react-hook-form\";\nimport { z } from \"zod\";\nimport { Input } from \"@/components/ui/input\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Field } from \"@/registry/ui/field\";\n\nconst wait = (ms: number) =>\n  new Promise<void>((resolve) => {\n    setTimeout(resolve, ms);\n  });\n\nconst schema = z.object({\n  email: z.email(\"Enter a valid email.\"),\n  password: z.string().min(8, \"Password must be at least 8 characters.\"),\n});\n\ntype FormValues = z.infer<typeof schema>;\n\nconst Demo = () => {\n  const {\n    register,\n    handleSubmit,\n    formState: { errors, isSubmitting },\n  } = useForm<FormValues>({ resolver: standardSchemaResolver(schema) });\n\n  return (\n    <form\n      className=\"w-full max-w-md space-y-5\"\n      noValidate\n      onSubmit={handleSubmit(() => wait(800))}\n    >\n      <Field error={errors.email?.message} label=\"Email\" required>\n        <Input\n          placeholder=\"ada@example.com\"\n          type=\"email\"\n          {...register(\"email\")}\n        />\n      </Field>\n\n      <Field\n        description=\"At least 8 characters.\"\n        error={errors.password?.message}\n        label=\"Password\"\n        required\n      >\n        <Input type=\"password\" {...register(\"password\")} />\n      </Field>\n\n      <AsyncButton loading={isSubmitting} type=\"submit\">\n        Create account\n      </AsyncButton>\n    </form>\n  );\n};\n\nexport default Demo;\n"
  },

  "input-group-demo": {
    component: React.lazy(() => import("./input-group-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { InputGroupButton } from \"@/components/ui/input-group\";\nimport { Field } from \"@/registry/ui/field\";\nimport { InputGroup } from \"@/registry/ui/input-group\";\n\nconst Demo = () => {\n  const [controlledValue, setControlledValue] = useState(\"draft\");\n  const [invited, setInvited] = useState(false);\n\n  return (\n    <div className=\"w-full max-w-md space-y-5\">\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-basic\">\n          Username\n        </label>\n        <InputGroup\n          autoComplete=\"username\"\n          id=\"input-group-basic\"\n          placeholder=\"ada-lovelace\"\n        />\n      </div>\n\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-amount\">\n          Amount in US dollars\n        </label>\n        <InputGroup\n          id=\"input-group-amount\"\n          inputMode=\"decimal\"\n          placeholder=\"0.00\"\n          startAddon=\"$\"\n        />\n      </div>\n\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-weight\">\n          Weight in kilograms\n        </label>\n        <InputGroup\n          endAddon=\"kg\"\n          id=\"input-group-weight\"\n          inputMode=\"decimal\"\n          placeholder=\"0\"\n        />\n      </div>\n\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-domain\">\n          HTTPS .com domain\n        </label>\n        <InputGroup\n          endAddon=\".com\"\n          id=\"input-group-domain\"\n          placeholder=\"example\"\n          startAddon=\"https://\"\n        />\n      </div>\n\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-invitee\">\n          Invitee\n        </label>\n        <InputGroup\n          endAddon={\n            <InputGroupButton onClick={() => setInvited(true)} type=\"button\">\n              Invite\n            </InputGroupButton>\n          }\n          id=\"input-group-invitee\"\n          placeholder=\"teammate@example.com\"\n          type=\"email\"\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-muted-foreground text-sm\"\n          role=\"status\"\n        >\n          {invited ? \"Invitation queued.\" : \"No invitation queued.\"}\n        </p>\n      </div>\n\n      <div className=\"space-y-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"input-group-controlled\">\n          Controlled value\n        </label>\n        <InputGroup\n          id=\"input-group-controlled\"\n          onChange={(event) => setControlledValue(event.currentTarget.value)}\n          value={controlledValue}\n        />\n        <p className=\"text-muted-foreground text-sm\">\n          Current value: {controlledValue || \"Empty\"}\n        </p>\n      </div>\n\n      <Field\n        description=\"Used if you lose access to your primary account.\"\n        error=\"Use a work email address.\"\n        label=\"Recovery email\"\n      >\n        <InputGroup defaultValue=\"ada@example\" type=\"email\" />\n      </Field>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "input-otp-demo": {
    component: React.lazy(() => import("./input-otp-demo")),
    codeString: "\"use client\";\n\nimport { REGEXP_ONLY_DIGITS } from \"input-otp\";\nimport { useState } from \"react\";\nimport { InputOTP } from \"@/registry/ui/input-otp\";\n\nconst Demo = () => {\n  const [value, setValue] = useState(\"\");\n  const [completed, setCompleted] = useState(\"\");\n\n  return (\n    <div className=\"grid w-full max-w-sm gap-6\">\n      <div className=\"grid gap-2\">\n        <label className=\"font-medium text-sm\" htmlFor=\"verification-code\">\n          Verification code\n        </label>\n        <InputOTP\n          aria-describedby=\"verification-help\"\n          groupSize={3}\n          id=\"verification-code\"\n          maxLength={6}\n          onChange={setValue}\n          onComplete={setCompleted}\n          pasteTransformer={(pasted) => pasted.replaceAll(\"-\", \"\")}\n          pattern={REGEXP_ONLY_DIGITS}\n          placeholder=\"••••••\"\n          value={value}\n        />\n        <p className=\"text-muted-foreground text-sm\" id=\"verification-help\">\n          Paste formats like 123-456. Value: {value || \"Empty\"}. Completed:{\" \"}\n          {completed || \"No\"}.\n        </p>\n      </div>\n\n      <InputOTP\n        aria-invalid=\"true\"\n        aria-label=\"Invalid verification code\"\n        groupSize={3}\n        maxLength={6}\n        value=\"000000\"\n      />\n\n      <InputOTP\n        aria-label=\"Disabled verification code\"\n        disabled\n        maxLength={4}\n      />\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "modal-alert-demo": {
    component: React.lazy(() => import("./modal-alert-demo")),
    codeString: "import { AsyncButton } from \"@/registry/ui/async-button\";\nimport { AlertModal } from \"@/registry/ui/modal\";\n\nconst Demo = () => (\n  <div>\n    <AlertModal\n      description=\"Modal Content\"\n      title=\"Alert Title\"\n      trigger={<AsyncButton>Alert Modal</AsyncButton>}\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "modal-alert-helper-demo": {
    component: React.lazy(() => import("./modal-alert-helper-demo")),
    codeString: "import { AsyncButton } from \"@/registry/ui/async-button\";\nimport { AlertModal } from \"@/registry/ui/modal\";\n\nconst Demo = () => (\n  <div className=\"space-x-2\">\n    <AsyncButton\n      onClick={() => {\n        AlertModal.alert({\n          title: \"Tips\",\n          description: \"Alert Content\",\n        });\n      }}\n    >\n      Click Alert\n    </AsyncButton>\n    <AsyncButton\n      onClick={async () => {\n        const ok = await AlertModal.confirm({\n          title: \"Tips\",\n          description:\n            \"If onConfirm or onCancel is asynchronous events, the button will automatically display loading\",\n          onConfirm: () =>\n            new Promise((resolve) => {\n              setTimeout(resolve, 1000);\n            }),\n        });\n        // Resolves true on confirm, false on cancel or Escape — never rejects.\n        console.log(ok ? \"confirmed\" : \"cancelled\");\n      }}\n    >\n      Click Confirm\n    </AsyncButton>\n    <AsyncButton\n      onClick={async () => {\n        await AlertModal.alert({\n          title: \"Tips1\",\n          description: \"Alert Content-1\",\n        });\n        await AlertModal.alert({\n          title: \"Tips2\",\n          description: \"Alert Content-2\",\n        });\n      }}\n    >\n      Alert Step by Step\n    </AsyncButton>\n    <AsyncButton\n      onClick={async () => {\n        await AlertModal.alert({\n          title: \"Tips1\",\n          description: (\n            <div>\n              <div>Alert Content-1</div>\n              <div>Alert Content-1</div>\n              <div>Alert Content-1</div>\n              <div>Alert Content-1</div>\n              <div>Alert Content-1</div>\n            </div>\n          ),\n          onConfirm: async () => {\n            await AlertModal.alert({\n              title: \"Tips1-1\",\n              description: \"Alert Content-1-1\",\n            });\n          },\n        });\n      }}\n    >\n      Alert Step In Step\n    </AsyncButton>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "modal-demo": {
    component: React.lazy(() => import("./modal-demo")),
    codeString: "import { useState } from \"react\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Modal } from \"@/registry/ui/modal\";\n\nconst wait = (ms: number) =>\n  new Promise<void>((resolve) => {\n    setTimeout(resolve, ms);\n  });\n\nconst Demo = () => {\n  const [showModal, setShowModal] = useState(false);\n\n  return (\n    <div className=\"space-x-2\">\n      <Modal\n        description=\"The flat footer needs no controlled state — OK closes after the async handler resolves.\"\n        onConfirm={() => wait(1000)}\n        title=\"Flat footer\"\n        trigger={<AsyncButton>Flat Confirm Footer</AsyncButton>}\n      >\n        <div>Modal Content</div>\n      </Modal>\n\n      <Modal\n        footer={\n          <div className=\"space-x-2\">\n            <AsyncButton\n              onClick={() => {\n                setShowModal(false);\n              }}\n              variant=\"ghost\"\n            >\n              Cancel\n            </AsyncButton>\n            <AsyncButton>Save</AsyncButton>\n          </div>\n        }\n        onOpenChange={setShowModal}\n        open={showModal}\n        title=\"Custom footer\"\n        trigger={<AsyncButton variant=\"outline\">Custom Footer</AsyncButton>}\n      >\n        <div>Modal Content</div>\n        <div>Modal Content</div>\n        <div>Modal Content</div>\n      </Modal>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "modal-helper-holder-demo": {
    component: React.lazy(() => import("./modal-helper-holder-demo")),
    codeString: "import { useRef, useState } from \"react\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Modal } from \"@/registry/ui/modal\";\n\nconst CommandModalModal = Modal.create(({ count }: { count: number }) => {\n  const modal = Modal.useModal();\n\n  return (\n    <Modal\n      {...modal.modalProps}\n      footer={\n        <div className=\"space-x-2\">\n          <AsyncButton\n            onClick={() => {\n              modal.hide();\n            }}\n            variant=\"ghost\"\n          >\n            Cancel\n          </AsyncButton>\n          <AsyncButton>Save</AsyncButton>\n        </div>\n      }\n      title=\"Modal Will Update by props\"\n    >\n      <p>AnyModalContent: {count}</p>\n      <p>Count will be updated in 1 second</p>\n    </Modal>\n  );\n});\n\nconst Demo = () => {\n  const [action, ModalHolder] = Modal.useModalHolder(CommandModalModal);\n\n  const [count, setCount] = useState(0);\n  const countRef = useRef<NodeJS.Timeout | null>(null);\n\n  const handleClick = () => {\n    countRef.current && clearInterval(countRef.current);\n    action.show();\n\n    countRef.current = setInterval(() => {\n      setCount((c) => c + 1);\n    }, 1000);\n  };\n\n  return (\n    <Modal.Provider>\n      <AsyncButton onClick={handleClick}>Click Show Modal</AsyncButton>\n      <p>Current Count: {count}</p>\n      <ModalHolder count={count} />\n    </Modal.Provider>\n  );\n};\n\nexport default Demo;\n"
  },

  "pagination-demo": {
    component: React.lazy(() => import("./pagination-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Pagination } from \"@/registry/ui/pagination\";\n\nconst Demo = () => {\n  const [controlledValue, setControlledValue] = useState(4);\n  const [lastUncontrolledValue, setLastUncontrolledValue] = useState(3);\n\n  return (\n    <div className=\"grid w-full max-w-4xl gap-8 md:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Client controlled</h3>\n        <Pagination\n          aria-label=\"Controlled result pages\"\n          onValueChange={setControlledValue}\n          total={96}\n          value={controlledValue}\n        />\n        <p className=\"text-center text-muted-foreground text-xs\">\n          Current page: {controlledValue}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Client uncontrolled</h3>\n        <Pagination\n          aria-label=\"Uncontrolled result pages\"\n          defaultValue={3}\n          onValueChange={setLastUncontrolledValue}\n          total={72}\n        />\n        <p className=\"text-center text-muted-foreground text-xs\">\n          Last reported page: {lastUncontrolledValue}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Route navigation</h3>\n        <Pagination\n          aria-label=\"Report route pages\"\n          getPageHref={(page) => `/docs/components/pagination?page=${page}`}\n          total={120}\n          value={6}\n        />\n        <p className=\"text-center text-muted-foreground text-xs\">\n          Genuine links preserve native browser navigation.\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Compact range</h3>\n        <Pagination\n          aria-label=\"Compact result pages\"\n          boundaryCount={2}\n          onValueChange={() => undefined}\n          siblingCount={0}\n          total={1000}\n          value={50}\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Disabled</h3>\n        <Pagination\n          aria-label=\"Disabled result pages\"\n          defaultValue={2}\n          disabled\n          onValueChange={() => undefined}\n          total={50}\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Presentation</h3>\n        <Pagination\n          aria-label=\"Styled result pages\"\n          contentClassName=\"rounded-xl border bg-muted/30 p-1\"\n          linkClassName=\"rounded-full\"\n          nextClassName=\"text-primary\"\n          onValueChange={() => undefined}\n          previousClassName=\"text-primary\"\n          total={80}\n          value={4}\n        />\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "popover-demo": {
    component: React.lazy(() => import("./popover-demo")),
    codeString: "import { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Popover } from \"@/registry/ui/popover\";\n\nconst Demo = () => (\n  <div className=\"flex flex-wrap gap-4\">\n    <Popover\n      content={\n        <div className=\"grid gap-2 text-muted-foreground\">\n          <div>Width, height and other layout options.</div>\n          <div>Set the dimensions for the layer.</div>\n        </div>\n      }\n      description=\"Set the dimensions for the layer.\"\n      footer={\n        <div className=\"flex justify-end\">\n          <AsyncButton size=\"sm\">Save</AsyncButton>\n        </div>\n      }\n      title=\"Dimensions\"\n    >\n      <AsyncButton variant=\"outline\">Open popover</AsyncButton>\n    </Popover>\n\n    <Popover\n      align=\"start\"\n      content=\"Aligned to the start edge, opening on the right.\"\n      side=\"right\"\n    >\n      <AsyncButton variant=\"outline\">Positioned (right / start)</AsyncButton>\n    </Popover>\n\n    <Popover content=\"This one starts open via defaultOpen.\" defaultOpen>\n      <AsyncButton variant=\"outline\">Default open</AsyncButton>\n    </Popover>\n  </div>\n);\n\nexport default Demo;\n"
  },

  "progress-demo": {
    component: React.lazy(() => import("./progress-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { Progress } from \"@/registry/ui/progress\";\n\nconst Demo = () => {\n  const [releaseValue, setReleaseValue] = useState(75);\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-6 sm:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Basic</h3>\n        <Progress label=\"Upload progress\" value={56} />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Complete</h3>\n        <Progress label=\"Deployment progress\" value={100} />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Indeterminate</h3>\n        <Progress label=\"Background sync progress\" value={null} />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Hidden value</h3>\n        <Progress label=\"Indexing progress\" showValue={false} value={64} />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Visually hidden label</h3>\n        <Progress\n          label=\"Profile import progress\"\n          labelClassName=\"sr-only\"\n          value={42}\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Custom accessible value</h3>\n        <Progress\n          aria-valuetext=\"1 of 4 batches\"\n          label=\"Archive progress\"\n          value={25}\n        />\n      </section>\n\n      <section className=\"space-y-3 sm:col-span-2\">\n        <h3 className=\"font-medium text-sm\">Caller-controlled advancement</h3>\n        <Progress label=\"Release rollout progress\" value={releaseValue} />\n        <Button\n          disabled={releaseValue === 100}\n          onClick={() => setReleaseValue(100)}\n          size=\"sm\"\n          type=\"button\"\n          variant=\"outline\"\n        >\n          Complete rollout\n        </Button>\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "radio-group-demo": {
    component: React.lazy(() => import("./radio-group-demo")),
    codeString: "import { RadioGroup } from \"@/registry/ui/radio-group\";\n\nconst Demo = () => (\n  <div className=\"space-y-8\">\n    <RadioGroup\n      defaultValue=\"comfortable\"\n      items={[\n        { label: \"Default\", value: \"default\" },\n        { label: \"Comfortable\", value: \"comfortable\" },\n        { disabled: true, label: \"Compact (disabled)\", value: \"compact\" },\n      ]}\n    />\n\n    <RadioGroup\n      defaultValue=\"free\"\n      items={[\n        {\n          description: \"Up to 3 projects, community support.\",\n          label: \"Free\",\n          value: \"free\",\n        },\n        {\n          description: \"Unlimited projects, priority support.\",\n          label: \"Pro\",\n          value: \"pro\",\n        },\n      ]}\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "select-async-demo": {
    component: React.lazy(() => import("./select-async-demo")),
    codeString: "\"use client\";\n\nimport { Select, type SelectItem } from \"@/registry/ui/select\";\n\nconst COUNTRIES: SelectItem[] = [\n  { label: \"Argentina\", value: \"ar\" },\n  { label: \"Australia\", value: \"au\" },\n  { label: \"Brazil\", value: \"br\" },\n  { label: \"Canada\", value: \"ca\" },\n  { label: \"China\", value: \"cn\" },\n  { label: \"France\", value: \"fr\" },\n  { label: \"Germany\", value: \"de\" },\n  { label: \"India\", value: \"in\" },\n  { label: \"Italy\", value: \"it\" },\n  { label: \"Japan\", value: \"jp\" },\n  { label: \"Mexico\", value: \"mx\" },\n  { label: \"Netherlands\", value: \"nl\" },\n  { label: \"Spain\", value: \"es\" },\n  { label: \"United Kingdom\", value: \"uk\" },\n  { label: \"United States\", value: \"us\" },\n];\n\nconst loadCountries = async (\n  _query: string,\n  signal: AbortSignal\n): Promise<SelectItem[]> => {\n  await new Promise<void>((resolve, reject) => {\n    const t = setTimeout(resolve, 600);\n    signal.addEventListener(\"abort\", () => {\n      clearTimeout(t);\n      reject(new DOMException(\"Aborted\", \"AbortError\"));\n    });\n  });\n  return COUNTRIES;\n};\n\nconst Demo = () => (\n  <div className=\"w-64\">\n    <Select\n      clearable\n      loadItems={loadCountries}\n      loadOn=\"open\"\n      placeholder=\"Search a country\"\n      searchable\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "select-demo": {
    component: React.lazy(() => import("./select-demo")),
    codeString: "import { Select } from \"@/registry/ui/select\";\n\nconst items = [\n  { label: \"Apple\", value: \"apple\" },\n  { label: \"Banana\", value: \"banana\" },\n  { label: \"Cherry\", value: \"cherry\" },\n  { label: \"Durian\", value: \"durian\" },\n  { label: \"Elderberry\", value: \"elderberry\" },\n];\n\nconst Demo = () => (\n  <div className=\"w-64\">\n    <Select items={items} placeholder=\"Pick a fruit\" />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "select-multiple-demo": {
    component: React.lazy(() => import("./select-multiple-demo")),
    codeString: "import { Select } from \"@/registry/ui/select\";\n\nconst items = [\n  { label: \"TypeScript\", value: \"typescript\" },\n  { label: \"JavaScript\", value: \"javascript\" },\n  { label: \"Python\", value: \"python\" },\n  { label: \"Rust\", value: \"rust\" },\n  { label: \"Go\", value: \"go\" },\n  { label: \"Java\", value: \"java\" },\n  { label: \"C++\", value: \"cpp\" },\n  { label: \"Ruby\", value: \"ruby\" },\n];\n\nconst Demo = () => (\n  <div className=\"w-80\">\n    <Select items={items} multiple placeholder=\"Pick languages\" />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "select-searchable-demo": {
    component: React.lazy(() => import("./select-searchable-demo")),
    codeString: "import { Select } from \"@/registry/ui/select\";\n\nconst items = [\n  { label: \"Afghanistan\", value: \"af\" },\n  { label: \"Albania\", value: \"al\" },\n  { label: \"Algeria\", value: \"dz\" },\n  { label: \"Argentina\", value: \"ar\" },\n  { label: \"Australia\", value: \"au\" },\n  { label: \"Austria\", value: \"at\" },\n  { label: \"Belgium\", value: \"be\" },\n  { label: \"Brazil\", value: \"br\" },\n  { label: \"Canada\", value: \"ca\" },\n  { label: \"Chile\", value: \"cl\" },\n  { label: \"China\", value: \"cn\" },\n  { label: \"Colombia\", value: \"co\" },\n  { label: \"Denmark\", value: \"dk\" },\n  { label: \"Egypt\", value: \"eg\" },\n  { label: \"Finland\", value: \"fi\" },\n  { label: \"France\", value: \"fr\" },\n  { label: \"Germany\", value: \"de\" },\n  { label: \"Greece\", value: \"gr\" },\n  { label: \"India\", value: \"in\" },\n  { label: \"Indonesia\", value: \"id\" },\n  { label: \"Italy\", value: \"it\" },\n  { label: \"Japan\", value: \"jp\" },\n  { label: \"Mexico\", value: \"mx\" },\n  { label: \"Netherlands\", value: \"nl\" },\n  { label: \"Norway\", value: \"no\" },\n  { label: \"Poland\", value: \"pl\" },\n  { label: \"Portugal\", value: \"pt\" },\n  { label: \"Russia\", value: \"ru\" },\n  { label: \"Spain\", value: \"es\" },\n  { label: \"Sweden\", value: \"se\" },\n  { label: \"Switzerland\", value: \"ch\" },\n  { label: \"United Kingdom\", value: \"gb\" },\n  { label: \"United States\", value: \"us\" },\n];\n\nconst Demo = () => (\n  <div className=\"w-64\">\n    <Select clearable items={items} placeholder=\"Search a country\" searchable />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "select-server-search-demo": {
    component: React.lazy(() => import("./select-server-search-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Select, type SelectItem } from \"@/registry/ui/select\";\n\nconst USERS: SelectItem[] = [\n  { label: \"Ada Lovelace\", value: \"ada\" },\n  { label: \"Alan Turing\", value: \"alan\" },\n  { label: \"Barbara Liskov\", value: \"barbara\" },\n  { label: \"Donald Knuth\", value: \"donald\" },\n  { label: \"Edsger Dijkstra\", value: \"edsger\" },\n  { label: \"Grace Hopper\", value: \"grace\" },\n  { label: \"John von Neumann\", value: \"john\" },\n  { label: \"Linus Torvalds\", value: \"linus\" },\n  { label: \"Margaret Hamilton\", value: \"margaret\" },\n  { label: \"Richard Stallman\", value: \"richard\" },\n  { label: \"Tim Berners-Lee\", value: \"tim\" },\n  { label: \"Yukihiro Matsumoto\", value: \"yukihiro\" },\n];\n\nconst searchUsers = async (\n  query: string,\n  signal: AbortSignal\n): Promise<SelectItem[]> => {\n  await new Promise<void>((resolve, reject) => {\n    const t = setTimeout(resolve, 450);\n    signal.addEventListener(\"abort\", () => {\n      clearTimeout(t);\n      reject(new DOMException(\"Aborted\", \"AbortError\"));\n    });\n  });\n  const q = query.trim().toLowerCase();\n  if (!q) {\n    return USERS.slice(0, 6);\n  }\n  return USERS.filter((u) => String(u.label).toLowerCase().includes(q)).slice(\n    0,\n    8\n  );\n};\n\nconst Demo = () => {\n  const [value, setValue] = useState<string[]>([]);\n  return (\n    <div className=\"flex w-72 flex-col gap-2\">\n      <Select\n        debounceMs={250}\n        loadItems={searchUsers}\n        multiple\n        onValueChange={setValue}\n        placeholder=\"Search reviewers\"\n        serverSideFilter\n        value={value}\n      />\n      <p className=\"text-muted-foreground text-xs\">\n        Selected:{\" \"}\n        <code className=\"text-foreground\">\n          {value.length === 0 ? \"—\" : value.join(\", \")}\n        </code>\n      </p>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "sheet-demo": {
    component: React.lazy(() => import("./sheet-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Textarea } from \"@/components/ui/textarea\";\nimport { AsyncButton } from \"@/registry/ui/async-button\";\nimport { Sheet } from \"@/registry/ui/sheet\";\n\nconst ACTIVITY_ITEMS = Array.from(\n  { length: 18 },\n  (_, index) => `Activity item ${index + 1}`\n);\n\nconst Demo = () => {\n  const [controlledOpen, setControlledOpen] = useState(false);\n  const [workflowOpen, setWorkflowOpen] = useState(false);\n\n  return (\n    <div className=\"flex flex-wrap gap-3\">\n      <Sheet\n        content={\n          <div className=\"grid gap-4\">\n            <div className=\"grid gap-2\">\n              <Label htmlFor=\"sheet-name\">Name</Label>\n              <Input defaultValue=\"Ada Lovelace\" id=\"sheet-name\" />\n            </div>\n            <div className=\"grid gap-2\">\n              <Label htmlFor=\"sheet-bio\">Bio</Label>\n              <Textarea\n                defaultValue=\"Building thoughtful interfaces.\"\n                id=\"sheet-bio\"\n              />\n            </div>\n          </div>\n        }\n        description=\"Update the profile shown to your team.\"\n        footer={\n          <div className=\"flex justify-end\">\n            <AsyncButton>Save changes</AsyncButton>\n          </div>\n        }\n        title=\"Account settings\"\n        trigger={\n          <AsyncButton variant=\"outline\">Open account sheet</AsyncButton>\n        }\n      />\n\n      <Sheet\n        content={\n          <div className=\"space-y-3 text-muted-foreground\">\n            <p>The application owns this sheet's open state.</p>\n            <p>Its footer is caller-owned and closes explicitly.</p>\n          </div>\n        }\n        footer={\n          <AsyncButton\n            onClick={() => setControlledOpen(false)}\n            variant=\"outline\"\n          >\n            Close controlled sheet\n          </AsyncButton>\n        }\n        onOpenChange={setControlledOpen}\n        open={controlledOpen}\n        side=\"left\"\n        title=\"Controlled inspector\"\n        trigger={\n          <AsyncButton variant=\"outline\">Open controlled sheet</AsyncButton>\n        }\n      />\n\n      <Sheet\n        content={\n          <ol className=\"grid gap-3\">\n            {ACTIVITY_ITEMS.map((item) => (\n              <li className=\"rounded-lg border p-3\" key={item}>\n                {item}\n              </li>\n            ))}\n          </ol>\n        }\n        description=\"The body scrolls independently while the action stays available.\"\n        footer={\n          <AsyncButton onClick={() => setWorkflowOpen(false)}>\n            Finish workflow\n          </AsyncButton>\n        }\n        onOpenChange={setWorkflowOpen}\n        open={workflowOpen}\n        showCloseButton={false}\n        side=\"bottom\"\n        title=\"Recent activity\"\n        trigger={\n          <AsyncButton variant=\"outline\">Open activity sheet</AsyncButton>\n        }\n      />\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "slider-demo": {
    component: React.lazy(() => import("./slider-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { Slider } from \"@/registry/ui/slider\";\n\nconst Demo = () => {\n  const [temperature, setTemperature] = useState(20);\n  const [submitted, setSubmitted] = useState(\"not submitted\");\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-6 sm:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Basic</h3>\n        <Slider defaultValue={40} label=\"Volume\" />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Controlled</h3>\n        <Slider\n          label=\"Temperature\"\n          max={50}\n          min={-20}\n          onValueChange={setTemperature}\n          step={5}\n          value={temperature}\n        />\n        <p className=\"text-muted-foreground text-xs\">\n          Controlled value: {temperature}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Custom bounds and steps</h3>\n        <Slider\n          defaultValue={100}\n          label=\"Zoom\"\n          largeStep={50}\n          max={200}\n          min={50}\n          step={10}\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Hidden value</h3>\n        <Slider defaultValue={65} label=\"Opacity\" showValue={false} />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Disabled</h3>\n        <Slider defaultValue={30} disabled label=\"Unavailable volume\" />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Vertical</h3>\n        <Slider\n          className=\"h-40\"\n          defaultValue={60}\n          label=\"Vertical volume\"\n          orientation=\"vertical\"\n        />\n      </section>\n\n      <section className=\"space-y-3 sm:col-span-2\">\n        <h3 className=\"font-medium text-sm\">Native form</h3>\n        <form\n          className=\"space-y-3\"\n          onSubmit={(event) => {\n            event.preventDefault();\n            const data = new FormData(event.currentTarget);\n            setSubmitted(String(data.get(\"form-volume\") ?? \"missing\"));\n          }}\n        >\n          <Slider defaultValue={35} label=\"Form volume\" name=\"form-volume\" />\n          <Button size=\"sm\" type=\"submit\" variant=\"outline\">\n            Submit form\n          </Button>\n          <p\n            aria-live=\"polite\"\n            className=\"text-muted-foreground text-xs\"\n            role=\"status\"\n          >\n            Submitted value: {submitted}\n          </p>\n        </form>\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "switch-demo": {
    component: React.lazy(() => import("./switch-demo")),
    codeString: "\"use client\";\n\nimport { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { Switch } from \"@/registry/ui/switch\";\n\nconst Demo = () => {\n  const [controlled, setControlled] = useState(false);\n  const [submitted, setSubmitted] = useState(\"not submitted\");\n\n  return (\n    <div className=\"grid w-full max-w-2xl gap-6 sm:grid-cols-2\">\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Basic</h3>\n        <Switch label=\"Product updates\" />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">With description</h3>\n        <Switch\n          description=\"Receive a concise weekly summary.\"\n          label=\"Weekly summary\"\n        />\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Controlled</h3>\n        <Switch\n          checked={controlled}\n          label=\"Team availability\"\n          onCheckedChange={setControlled}\n        />\n        <p\n          aria-live=\"polite\"\n          className=\"text-muted-foreground text-xs\"\n          role=\"status\"\n        >\n          Controlled value: {controlled ? \"on\" : \"off\"}\n        </p>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">States</h3>\n        <div className=\"space-y-3\">\n          <Switch disabled label=\"Disabled option\" />\n          <Switch defaultChecked label=\"Read-only option\" readOnly />\n        </div>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Sizes</h3>\n        <div className=\"space-y-3\">\n          <Switch label=\"Small switch\" size=\"sm\" />\n          <Switch label=\"Default switch\" />\n        </div>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h3 className=\"font-medium text-sm\">Native form</h3>\n        <form\n          className=\"space-y-3\"\n          onSubmit={(event) => {\n            event.preventDefault();\n            const data = new FormData(event.currentTarget);\n            setSubmitted(String(data.get(\"digest\") ?? \"missing\"));\n          }}\n        >\n          <Switch\n            defaultChecked\n            label=\"Email digest\"\n            name=\"digest\"\n            uncheckedValue=\"disabled\"\n            value=\"enabled\"\n          />\n          <Button size=\"sm\" type=\"submit\" variant=\"outline\">\n            Submit form\n          </Button>\n          <p\n            aria-live=\"polite\"\n            className=\"text-muted-foreground text-xs\"\n            role=\"status\"\n          >\n            Submitted value: {submitted}\n          </p>\n        </form>\n      </section>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "table-demo": {
    component: React.lazy(() => import("./table-demo")),
    codeString: "import { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface User {\n  email: string;\n  id: string;\n  name: string;\n  role: string;\n}\n\nconst data: User[] = [\n  { email: \"ada@example.com\", id: \"1\", name: \"Ada Lovelace\", role: \"Owner\" },\n  {\n    email: \"linus@example.com\",\n    id: \"2\",\n    name: \"Linus Torvalds\",\n    role: \"Admin\",\n  },\n  { email: \"grace@example.com\", id: \"3\", name: \"Grace Hopper\", role: \"Member\" },\n];\n\nconst columns = defineColumns<User>()([\n  { dataIndex: \"name\", key: \"name\", title: \"Name\" },\n  { dataIndex: \"email\", key: \"email\", title: \"Email\" },\n  { align: \"right\", dataIndex: \"role\", key: \"role\", title: \"Role\" },\n]);\n\nconst Demo = () => (\n  <div className=\"rounded-md border\">\n    <Table\n      aria-label=\"Team members\"\n      columns={columns}\n      dataSource={data}\n      rowKey=\"id\"\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "table-loading-empty-demo": {
    component: React.lazy(() => import("./table-loading-empty-demo")),
    codeString: "import { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface Row {\n  id: string;\n  owner: string;\n  task: string;\n}\n\nconst sample: Row[] = [\n  { id: \"t1\", owner: \"Ada\", task: \"Design table API\" },\n  { id: \"t2\", owner: \"Linus\", task: \"Ship docs\" },\n];\n\nconst columns = defineColumns<Row>()([\n  { dataIndex: \"task\", key: \"task\", title: \"Task\" },\n  { dataIndex: \"owner\", key: \"owner\", title: \"Owner\" },\n]);\n\ntype Mode = \"data\" | \"loading\" | \"empty\";\n\nconst Demo = () => {\n  const [mode, setMode] = useState<Mode>(\"data\");\n  const dataSource = mode === \"data\" ? sample : [];\n\n  return (\n    <div className=\"space-y-3\">\n      <div className=\"flex gap-2\">\n        <Button\n          onClick={() => setMode(\"data\")}\n          size=\"sm\"\n          variant={mode === \"data\" ? \"default\" : \"outline\"}\n        >\n          With data\n        </Button>\n        <Button\n          onClick={() => setMode(\"loading\")}\n          size=\"sm\"\n          variant={mode === \"loading\" ? \"default\" : \"outline\"}\n        >\n          Loading\n        </Button>\n        <Button\n          onClick={() => setMode(\"empty\")}\n          size=\"sm\"\n          variant={mode === \"empty\" ? \"default\" : \"outline\"}\n        >\n          Empty\n        </Button>\n      </div>\n      <div className=\"rounded-md border\">\n        <Table\n          caption=\"Sprint backlog\"\n          columns={columns}\n          dataSource={dataSource}\n          emptyMessage=\"Nothing to do — go outside.\"\n          loading={mode === \"loading\"}\n          loadingMessage=\"Fetching tasks…\"\n          rowKey=\"id\"\n        />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "table-render-demo": {
    component: React.lazy(() => import("./table-render-demo")),
    codeString: "import { useState } from \"react\";\nimport { Button } from \"@/components/ui/button\";\nimport { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface Order {\n  amount: number;\n  createdAt: string;\n  customer: string;\n  id: string;\n  status: \"paid\" | \"pending\" | \"refunded\";\n}\n\nconst data: Order[] = [\n  {\n    amount: 1299,\n    createdAt: \"2026-05-12\",\n    customer: \"Acme Inc.\",\n    id: \"ord_001\",\n    status: \"paid\",\n  },\n  {\n    amount: 480,\n    createdAt: \"2026-05-14\",\n    customer: \"Globex\",\n    id: \"ord_002\",\n    status: \"pending\",\n  },\n  {\n    amount: 75,\n    createdAt: \"2026-05-15\",\n    customer: \"Initech\",\n    id: \"ord_003\",\n    status: \"refunded\",\n  },\n];\n\nconst formatter = new Intl.NumberFormat(\"en-US\", {\n  currency: \"USD\",\n  style: \"currency\",\n});\n\nconst statusClass: Record<Order[\"status\"], string> = {\n  paid: \"bg-green-100 text-green-800\",\n  pending: \"bg-amber-100 text-amber-800\",\n  refunded: \"bg-zinc-100 text-zinc-800\",\n};\n\nconst Demo = () => {\n  const [viewing, setViewing] = useState<string | null>(null);\n\n  const columns = defineColumns<Order>()([\n    { dataIndex: \"id\", key: \"id\", title: \"Order\" },\n    { dataIndex: \"customer\", key: \"customer\", title: \"Customer\" },\n    {\n      align: \"right\",\n      dataIndex: \"amount\",\n      key: \"amount\",\n      // `value` narrows to `number`.\n      render: (value) => formatter.format(value),\n      title: \"Amount\",\n    },\n    {\n      dataIndex: \"status\",\n      key: \"status\",\n      // `value` narrows to Order[\"status\"].\n      render: (value) => (\n        <span\n          className={`inline-flex rounded-full px-2 py-0.5 font-medium text-xs ${statusClass[value]}`}\n        >\n          {value}\n        </span>\n      ),\n      title: \"Status\",\n    },\n    { dataIndex: \"createdAt\", key: \"createdAt\", title: \"Date\" },\n    {\n      align: \"right\",\n      key: \"actions\",\n      // No dataIndex — `value` is `undefined`, pull from `record` instead.\n      render: (_value, record) => (\n        <Button\n          onClick={() => setViewing(record.id)}\n          size=\"sm\"\n          variant=\"outline\"\n        >\n          View\n        </Button>\n      ),\n      title: \"Actions\",\n    },\n  ]);\n\n  return (\n    <div className=\"space-y-3\">\n      <p className=\"text-muted-foreground text-sm\">\n        {viewing ? `Viewing ${viewing}` : \"Click a row's View button\"}\n      </p>\n      <div className=\"rounded-md border\">\n        <Table\n          aria-label=\"Recent orders\"\n          columns={columns}\n          dataSource={data}\n          rowKey=\"id\"\n        />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "table-row-classname-demo": {
    component: React.lazy(() => import("./table-row-classname-demo")),
    codeString: "import { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface Server {\n  cpu: number;\n  id: string;\n  name: string;\n  region: string;\n}\n\nconst data: Server[] = [\n  { cpu: 32, id: \"s1\", name: \"api-1\", region: \"us-east-1\" },\n  { cpu: 91, id: \"s2\", name: \"api-2\", region: \"us-east-1\" },\n  { cpu: 12, id: \"s3\", name: \"worker-1\", region: \"eu-west-1\" },\n  { cpu: 88, id: \"s4\", name: \"worker-2\", region: \"ap-south-1\" },\n];\n\n// Three-state status so the high-CPU signal travels through icon + text +\n// colour — color alone fails colour-blind users (WCAG 1.4.1).\nconst statusFor = (cpu: number) => {\n  if (cpu >= 80) {\n    return \"hot\" as const;\n  }\n  if (cpu >= 60) {\n    return \"warm\" as const;\n  }\n  return \"ok\" as const;\n};\n\nconst statusIcon: Record<ReturnType<typeof statusFor>, string> = {\n  hot: \"▲\",\n  ok: \"·\",\n  warm: \"•\",\n};\n\nconst columns = defineColumns<Server>()([\n  { dataIndex: \"name\", key: \"name\", title: \"Server\" },\n  { dataIndex: \"region\", key: \"region\", title: \"Region\" },\n  {\n    align: \"right\",\n    dataIndex: \"cpu\",\n    key: \"cpu\",\n    // `value` narrows to `number`.\n    render: (value) => {\n      const status = statusFor(value);\n      return (\n        <span className=\"inline-flex items-center gap-1.5\">\n          <span aria-hidden className=\"font-mono\">\n            {statusIcon[status]}\n          </span>\n          <span>{value}%</span>\n          <span className=\"sr-only\">({status})</span>\n        </span>\n      );\n    },\n    title: \"CPU\",\n  },\n]);\n\nconst Demo = () => (\n  <div className=\"rounded-md border\">\n    <Table\n      aria-label=\"Server CPU usage\"\n      columns={columns}\n      dataSource={data}\n      rowClassName={(record) =>\n        record.cpu >= 80 ? \"bg-destructive/10\" : undefined\n      }\n      rowKey=\"id\"\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "table-row-click-demo": {
    component: React.lazy(() => import("./table-row-click-demo")),
    codeString: "import { useState } from \"react\";\nimport { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface Member {\n  email: string;\n  id: string;\n  name: string;\n  role: \"owner\" | \"admin\" | \"member\";\n}\n\nconst data: Member[] = [\n  { email: \"ada@example.com\", id: \"u1\", name: \"Ada Lovelace\", role: \"owner\" },\n  {\n    email: \"linus@example.com\",\n    id: \"u2\",\n    name: \"Linus Torvalds\",\n    role: \"admin\",\n  },\n  {\n    email: \"grace@example.com\",\n    id: \"u3\",\n    name: \"Grace Hopper\",\n    role: \"member\",\n  },\n  { email: \"alan@example.com\", id: \"u4\", name: \"Alan Turing\", role: \"member\" },\n];\n\nconst columns = defineColumns<Member>()([\n  { dataIndex: \"name\", key: \"name\", title: \"Name\" },\n  { dataIndex: \"email\", key: \"email\", title: \"Email\" },\n  { dataIndex: \"role\", key: \"role\", title: \"Role\" },\n]);\n\nconst Demo = () => {\n  const [viewing, setViewing] = useState<string | null>(null);\n  const [selected, setSelected] = useState<string[]>([]);\n\n  return (\n    <div className=\"space-y-3\">\n      <p className=\"text-muted-foreground text-sm\">\n        {viewing ? `Viewing ${viewing}` : \"Click a row, or Tab + Enter / Space\"}\n        {selected.length > 0 ? ` · selected: ${selected.join(\", \")}` : \"\"}\n      </p>\n      <div className=\"rounded-md border\">\n        <Table\n          aria-label=\"Team members\"\n          columns={columns}\n          dataSource={data}\n          getCheckboxProps={(record) => ({\n            \"aria-label\": `Select ${record.name}`,\n          })}\n          onRowClick={(record) => setViewing(record.id)}\n          onSelectedRowKeysChange={setSelected}\n          rowKey=\"id\"\n          selectable\n          selectedRowKeys={selected}\n        />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "table-selection-demo": {
    component: React.lazy(() => import("./table-selection-demo")),
    codeString: "import { useState } from \"react\";\nimport { defineColumns, Table } from \"@/registry/ui/table\";\n\ninterface Member {\n  id: string;\n  name: string;\n  role: \"owner\" | \"admin\" | \"member\";\n}\n\nconst data: Member[] = [\n  { id: \"u1\", name: \"Ada Lovelace\", role: \"owner\" },\n  { id: \"u2\", name: \"Linus Torvalds\", role: \"admin\" },\n  { id: \"u3\", name: \"Grace Hopper\", role: \"member\" },\n  { id: \"u4\", name: \"Alan Turing\", role: \"member\" },\n];\n\nconst columns = defineColumns<Member>()([\n  { dataIndex: \"name\", key: \"name\", title: \"Name\" },\n  { dataIndex: \"role\", key: \"role\", title: \"Role\" },\n]);\n\nconst Demo = () => {\n  const [selected, setSelected] = useState<string[]>([]);\n\n  return (\n    <div className=\"space-y-3\">\n      <p className=\"text-muted-foreground text-sm\">\n        Selected: {selected.length === 0 ? \"none\" : selected.join(\", \")} (the\n        owner row is non-selectable)\n      </p>\n      <div className=\"rounded-md border\">\n        <Table\n          aria-label=\"Team members\"\n          columns={columns}\n          dataSource={data}\n          getCheckboxProps={(record) => ({\n            // Human-readable label so screen readers announce the row\n            // identity, not the opaque rowKey.\n            \"aria-label\": `Select ${record.name}`,\n            disabled: record.role === \"owner\",\n          })}\n          onSelectedRowKeysChange={setSelected}\n          rowKey=\"id\"\n          selectable\n          selectedRowKeys={selected}\n        />\n      </div>\n    </div>\n  );\n};\n\nexport default Demo;\n"
  },

  "tabs-demo": {
    component: React.lazy(() => import("./tabs-demo")),
    codeString: "import { Tabs } from \"@/registry/ui/tabs\";\n\nconst Demo = () => (\n  <div className=\"space-y-8\">\n    <Tabs\n      defaultValue=\"first\"\n      items={[\n        {\n          trigger: \"First\",\n          value: \"first\",\n          content: (\n            <div className=\"rounded-2xl border bg-accent p-6\">\n              First Content\n            </div>\n          ),\n        },\n        {\n          trigger: \"Second\",\n          value: \"second\",\n          content: (\n            <div className=\"rounded-2xl border bg-accent-foreground p-6 text-accent\">\n              Second Content\n            </div>\n          ),\n        },\n      ]}\n    />\n\n    <Tabs\n      defaultValue=\"overview\"\n      items={[\n        {\n          trigger: \"Overview\",\n          value: \"overview\",\n          content: <div className=\"p-2\">Line variant</div>,\n        },\n        {\n          trigger: \"Settings\",\n          value: \"settings\",\n          content: <div className=\"p-2\">Settings panel</div>,\n        },\n        {\n          disabled: true,\n          trigger: \"Billing\",\n          value: \"billing\",\n          content: null,\n        },\n      ]}\n      variant=\"line\"\n    />\n  </div>\n);\n\nexport default Demo;\n"
  },

  "tooltip-demo": {
    component: React.lazy(() => import("./tooltip-demo")),
    codeString: "import { Button } from \"@/components/ui/button\";\nimport { Tooltip } from \"@/registry/ui/tooltip\";\n\nconst Demo = () => (\n  <div className=\"flex flex-wrap items-center gap-4\">\n    <Tooltip content=\"Add to your library\">\n      <Button variant=\"outline\">Hover me</Button>\n    </Tooltip>\n\n    <Tooltip content=\"Shown below the trigger\" side=\"bottom\">\n      <Button variant=\"outline\">Bottom</Button>\n    </Tooltip>\n\n    <Tooltip content=\"Opens after 500ms\" delay={500}>\n      <Button variant=\"outline\">Delayed</Button>\n    </Tooltip>\n  </div>\n);\n\nexport default Demo;\n"
  },
} as const
